id/nbt/p401381463","https://data.bibliotheken.nl/id/nbt/p411240706","https://data.bibliotheken.nl/id/nbt/p396542727","https://data.bibliotheken.nl/id/nbt/p423479237","https://data.bibliotheken.nl/id/nbt/p412522322","https://data.bibliotheken.nl/id/nbt/p412975432"]},{"type":"cover_front_review","sha256":"5ea5df7bed464755e76e89b5b6658280aca7202debe0a803a18b06aad516f849","cover_id":8063733,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/8063733-L.jpg?default=false","edition_id":987219002,"bound_title":"Een tijd voor empathie","reviewed_at":"2026-11-02T21:47:08.214+00:00","bound_isbn13":"9789046705223","evidence_url":"https://data.bibliotheken.nl/id/nbt/p401381463","review_batch":"nl-scale-20261102-020","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/8063733-M.jpg?default=false","bound_author_id":987319002},"before_row":null},{"key":{"work_id":987119003,"language":"nl"},"seq":3,"relation":"catalog_work_descriptions","after_row":{"text":"De familie Talamini trekt volgens een vaste traditie tussen de Italiaanse bergen en haar ijssalon in Rotterdam. Vader Giuseppe ziet het vak als een erfenis die moet worden doorgegeven. Zijn zoon Giovanni kiest echter voor de poëzie en bouwt een eigen loopbaan op. De jongere Luca neemt de zaak over. Wanneer hij zijn broer een ongebruikelijk verzoek doet, moet Giovanni opnieuw bepalen wat familie van hem mag verlangen. De roman verbindt ambacht en overgeleverde verwachtingen met de vrijheid om een ander leven te kiezen.","work_id":987119003,"evidence":[{"note":"Exact primary publisher DeBezigeBij book page credits Ernest van der Kwast for paperback9789023486381,2015,304p, matching KB full authority p239936248 Ernest Roelof Arend. Preserve existing Work; no author merge or universal popularity claim.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p390862975","http://data.bibliotheken.nl/id/nbt/p394953614","http://data.bibliotheken.nl/id/nbt/p377415057"],"reference":"work:6191","checked_at":"2026-11-02T21:47:08.214Z","canonical_name_resolution":"Exact title/ISBN9789023486381 credits Ernest van der Kwast in primary publisher page and KB title statement; linked full-name authority belongs to that exact book, not guessed by name."},{"type":"original_substantive_source_review","review":"content-review-034.json","sources":["https://www.debezigebij.nl/boek/de-ijsmakers/","https://openlibrary.org/works/OL20302179W","https://data.bibliotheken.nl/id/nbt/p390862975","https://data.bibliotheken.nl/id/nbt/p394953614","https://data.bibliotheken.nl/id/nbt/p377415057"]},{"type":"cover_front_review","sha256":"8899cbd4be7bdbdf40a877759a252de203264395a1643138418847df40fb906f","cover_id":8961510,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.debezigebij.nl/boek/de-ijsmakers/","reviewed_at":"2026-11-02T21:47:08.214+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-020","review_status":"approved","bound_author_id":987319003},"before_row":null},{"key":{"edition_id":987219003},"seq":4,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987119003,"evidence":[{"note":"Exact primary publisher DeBezigeBij book page credits Ernest van der Kwast for paperback9789023486381,2015,304p, matching KB full authority p239936248 Ernest Roelof Arend. Preserve existing Work; no author merge or universal popularity claim.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p390862975","http://data.bibliotheken.nl/id/nbt/p394953614","http://data.bibliotheken.nl/id/nbt/p377415057"],"reference":"work:6191","checked_at":"2026-11-02T21:47:08.214Z","canonical_name_resolution":"Exact title/ISBN9789023486381 credits Ernest van der Kwast in primary publisher page and KB title statement; linked full-name authority belongs to that exact book, not guessed by name."},{"type":"original_substantive_source_review","review":"content-review-034.json","sources":["https://www.debezigebij.nl/boek/de-ijsmakers/","https://openlibrary.org/works/OL20302179W","https://data.bibliotheken.nl/id/nbt/p390862975","https://data.bibliotheken.nl/id/nbt/p394953614","https://data.bibliotheken.nl/id/nbt/p377415057"]},{"type":"cover_front_review","sha256":"8899cbd4be7bdbdf40a877759a252de203264395a1643138418847df40fb906f","cover_id":8961510,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/8961510-L.jpg?default=false","edition_id":987219003,"bound_title":"De ijsmakers","reviewed_at":"2026-11-02T21:47:08.214+00:00","bound_isbn13":"9789023486381","evidence_url":"https://data.bibliotheken.nl/id/nbt/p390862975","review_batch":"nl-scale-20261102-020","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/8961510-M.jpg?default=false","bound_author_id":987319003},"before_row":null},{"key":{"work_id":987119001,"language":"nl"},"seq":5,"relation":"catalog_work_descriptions","after_row":{"text":"Zes vrienden besluiten begin jaren negentig samen een brouwerij in een Utrechtse werfkelder te beginnen. De avonden in hun stamcafé krijgen daarmee een zakelijk vervolg. Vijfentwintig jaar later reizen ze naar een boshut in Duitsland voordat zij de verkoop van hun bedrijf zullen tekenen. Het weekend biedt gelegenheid terug te kijken op levens die door vriendschap én samenwerking verbonden raakten. Ronald Giphart vertelt vanuit een gezamenlijk perspectief over ambities, liefde en de vraag wat van hun oorspronkelijke saamhorigheid overblijft wanneer een gedeelde onderneming eindigt.","work_id":987119001,"evidence":[{"note":"Primary publisher credits Ronald Giphart for this same novel; KB exact2019ISBN9789403160405 binds Ronald Edgar Giphart. NS historical Treinlezer coupon independently binds the exact2019ISBN and publisher. The primary publisher current2023paperback ISBN9789403131467 is another printing, not substituted.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p42222829X"],"reference":"work:1671","checked_at":"2026-11-02T21:47:08.214Z","canonical_name_resolution":"Exact2019ISBN title statement and linked full-name author p092801668 bind Ronald Edgar; same public author credit on publisher page and NS original coupon. No author merge."},{"type":"original_substantive_source_review","review":"content-review-035.json","sources":["https://www.debezigebij.nl/boek/alle-tijd/","https://www.ns.nl/binaries/_ht_1598454936582/content/assets/ns-nl/treinlezer/coupon---alle-tijd-van-ronald-giphart.pdf","https://openlibrary.org/works/OL24409454W","https://data.bibliotheken.nl/id/nbt/p42222829X"]},{"type":"cover_front_review","sha256":"aadab6371bb12de31d9594db84132249858c61ae71420048dfebda8a938e894e","cover_id":10952479,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.debezigebij.nl/boek/alle-tijd/","reviewed_at":"2026-11-02T21:47:08.214+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-020","review_status":"approved","bound_author_id":987319001},"before_row":null},{"key":{"edition_id":987219001},"seq":6,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987119001,"evidence":[{"note":"Primary publisher credits Ronald Giphart for this same novel; KB 